-- D1 数据库 schema & 初始数据
-- 执行方式: npx wrangler d1 execute ad-orders-db --file=db/schema.sql

CREATE TABLE IF NOT EXISTS orders (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    订单编号         TEXT UNIQUE NOT NULL,
    计划id           TEXT,
    计划名称         TEXT,
    计划优化目标     TEXT,
    用户下单时间     TEXT,
    支付属性         TEXT,
    订单类型         TEXT,
    订单来源         TEXT,
    订单金额_元      REAL,
    达人名称         TEXT,
    实付金额         REAL,
    数据月份         TEXT NOT NULL,
    来源sheet        TEXT,
    导入时间         TEXT DEFAULT (datetime('now', 'localtime'))
);

CREATE INDEX IF NOT EXISTS idx_订单编号 ON orders(订单编号);
CREATE INDEX IF NOT EXISTS idx_下单时间 ON orders(用户下单时间);
CREATE INDEX IF NOT EXISTS idx_达人名称 ON orders(达人名称);
CREATE INDEX IF NOT EXISTS idx_数据月份 ON orders(数据月份);
